from config import MAX_RETRIES, BASE_URL

MAX_WORKERS = 4


class Worker:
    def __init__(self, max_retries=MAX_RETRIES):
        self.max_retries = max_retries
        self.base_url = BASE_URL

    def execute(self, task):
        for _ in range(self.max_retries):
            if task():
                return True
        return False
